    }

    return visible;
}

/// <summary>
/// Controls if the <c>PreferredInput</c> field is visible.
/// </summary>
/// <returns>true if the field is visible; otherwise, false.</returns>
public boolean avaIsFieldVisiblePreferredInput()
{
    boolean     ret;

    if (!this.UseExistingWork)
    {
        switch (this.WorkActivity)
        {
            case WHSWorkActivity::AVAChangePrinter:
                ret = true;
                break;
        }
    }

    return ret;
}

