/// <summary>
/// M.essl 11.03.2024
/// Controls if the <c>AVAWHSreceivingSO</c> field is visible.
/// </summary>
/// <returns>
/// true if the field is visible; otherwise, false.
/// </returns>
public boolean AVAIsWHSreceivingSO()
{
    if (this.WorkCreationProcess == WHSWorkCreationProcess::AVAWHSreceivingSO)
    {
        return true;
    }

    return false;
}

