/// <summary>
/// display Methode for the printer name
///  M.essl 19.03.2024
/// </summary>
/// <returns>
/// Returns the Name of the printer
/// </returns>
display public PrinterName avaPrinterName()
{
    SRSPrintDestinationSettings printJobSettings;
    PrinterName                 printerName;

    printJobSettings = new SRSPrintDestinationSettings(this.AVAPrinter);

    if (printJobSettings.printMediumType() == SRSPrintMediumType::Printer)
    {
        printerName = printJobSettings.printerName();
    }
    else
    {
        printerName = strFmt('%1', printJobSettings.printMediumType());
    }

    return printerName;
}

/// <summary>
/// The <c>AVAWHSRFMenuItemTableTbl_Extension</c> represents a extension of WHSRFMenuItemTable table.
///  M.essl 19.03.2024
/// </summary>
public void avaSetupPrinter()
{
    SRSPrintDestinationSettings printJobSettings;

    printJobSettings = new SRSPrintDestinationSettings(this.AVAPrinter);

    SrsReportRunUtil::showSettingsDialog(printJobSettings);

    this.AVAPrinter = printJobSettings.pack();
}

/// <summary>
/// Get the Printer Setting from rable
///  M.essl 19.03.2024
/// </summary>
/// <returns>
/// Returns the Printer settings for the closing container profil
/// </returns>
public SRSPrintDestinationSettings avaGetPrinterSettings()
{
    SRSPrintDestinationSettings printDestinationSettings;

    printDestinationSettings = new SRSPrintDestinationSettings(this.AVAPrinter);

    return printDestinationSettings;
}

/// <summary>
